{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Artemisinin, the closest structural analogue as a polycyclic lactone natural product, shows good absolute oral bioavailability after a single oral dose in patients with uncomplicated malaria, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Artesunate, an artemisinin derivative, has an absolute oral bioavailability of 61% in Thai patients, demonstrating that artemisinin-class lactones can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Dexamethasone, a polycyclic lipophilic molecule with multiple oxygen functionalities, has high absolute oral bioavailability (81.4 ± 15.8%) in humans, supporting the possibility of high F for the query's fused-ring system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Clarithromycin, a large polycyclic macrolide lactone, has about 55% oral bioavailability in humans, showing that lactone-rich natural products can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Limonin, another plant-derived polycyclic lactone, is reported to have poor bioavailability in humans; this is contradictory but lacks a quantitative F value and has lower structural similarity to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Fluticasone has negligible (<1%) oral bioavailability due to first-pass metabolism, but its corticosteroid thioester structure is too dissimilar to the query to override the quantitative high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a rigid, oxygenated polycyclic diterpenoid lactone. The most transferable quantitative evidence—artemisinin and its derivatives, plus other lactone-containing natural products—shows absolute oral bioavailability values above 20%. Qualitative 'low' reports for artemisinin/limonin are not threshold-specific and are outweighed by direct absolute measurements. Therefore, F ≥ 20% (high) is better supported, with low confidence due to low Morgan similarities.",
  "evidence_gaps": [
    "No direct experimental bioavailability value for the query molecule itself.",
    "All evidence molecules have low Morgan similarity (<0.2), limiting transferability.",
    "Several low-bioavailability reports are qualitative and do not establish F < 20%.",
    "No human data for the query; interspecies differences in first-pass metabolism may affect F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

